func (b *ProtoEventBlock) appendMeta(meta EventMeta) uint64 {
	idx := uint64(b.BlockNumber.Rows())
	b.BlockNumber.Append(meta.BlockNumber)
	b.BlockHash.Append(meta.BlockHash.Bytes())
	b.BlockTS.Append(meta.BlockTimestamp)
	b.ContractAddr.Append(meta.ContractAddress.Bytes())
	b.TxHash.Append(meta.TransactionHash.Bytes())
	b.TxIndex.Append(meta.TransactionIndex)
	b.LogIndex.Append(meta.LogIndex)
	return idx
}

