				ch <- DecodedLog{Value: &FixedProductMarketMakerFPMMFundingAdded{EventMeta: view.Meta(), Funder: view.Funder(), AmountsAdded: view.AmountsAdded(), SharesMinted: view.SharesMinted()}}
				FixedProductMarketMakerFPMMFundingAddedIdx++
